import{_ as t}from"./chunks/verwaltung-einstellungen-individual-einstellungen-farbe-statistik.PbWTgDXx.js";import{_ as r,o as s,c as a,a3 as i,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const d="/bilder/benutzer-einstellungen/verwaltung-einstellungen-individual-einstellungen-allgemeines.png",u="/bilder/benutzer-einstellungen/verwaltung-einstellungen-individual-einstellungen-bearbeiten-gesperrt.png",g="/bilder/benutzer-einstellungen/verwaltung-einstellungen-individual-einstellungen-silver-gui.png",o="/bilder/benutzer-einstellungen/verwaltung-einstellungen-individual-einstellungen-farbe-statistik-ergebnis.png",h="/bilder/benutzer-einstellungen/verwaltung-einstellungen-individual-einstellungen-andere.png",c="/bilder/benutzer-einstellungen/verwaltung-einstellungen-individual-einstellungen-sichtbare-spalten.png",m="/bilder/benutzer-einstellungen/einstellungen-globale-einstellungen-schnellzugriff-ausschnitt.png",p="/bilder/benutzer-einstellungen/einstellungen-individuelle-einstellungen-schnellzugriff-reiter.png",f="/bilder/benutzer-einstellungen/einstellungen-individuelle-einstellungen-schnellzugriff-reports-auswaehlen.png",b="/bilder/benutzer-einstellungen/einstellungen-individuelle-einstellungen-schnellzugriff-reportschnellzugriff.png",A=JSON.parse('{"title":"Anzeige und Bedienung individuell einstellen","description":"","frontmatter":{"title":"Anzeige und Bedienung individuell einstellen","source_pageid":404,"source_revision":6945},"headers":[],"relativePath":"administration/benutzer-einstellungen/individuelle-einstellungen-verwaltung-einstellungen.md","filePath":"administration/benutzer-einstellungen/individuelle-einstellungen-verwaltung-einstellungen.md"}'),z={name:"administration/benutzer-einstellungen/individuelle-einstellungen-verwaltung-einstellungen.md"};function v(w,l,S,k,_,E){return s(),a("div",null,[...l[0]||(l[0]=[i('<h1 id="anzeige-und-bedienung-individuell-einstellen" tabindex="-1">Anzeige und Bedienung individuell einstellen <a class="header-anchor" href="#anzeige-und-bedienung-individuell-einstellen" aria-label="Permalink to &quot;Anzeige und Bedienung individuell einstellen&quot;">​</a></h1><p>Passen Sie Anzeige und Bedienung an den angemeldeten Benutzer an. Die Einstellungen betreffen unter anderem Bearbeitungsmodus, sichtbare Spalten und Report-Schnellzugriffe.</p><h2 id="allgemeines" tabindex="-1">Allgemeines <a class="header-anchor" href="#allgemeines" aria-label="Permalink to &quot;Allgemeines&quot;">​</a></h2><p><a href="/bilder/benutzer-einstellungen/verwaltung-einstellungen-individual-einstellungen-allgemeines.png"><img src="'+d+'" alt="Individuelle Anzeige- und Bedieneinstellungen für den jeweiligen Benutzer." loading="lazy"></a></p><p><em>Individuelle Anzeige- und Bedieneinstellungen für den jeweiligen Benutzer.</em></p><p><a href="/bilder/benutzer-einstellungen/verwaltung-einstellungen-individual-einstellungen-bearbeiten-gesperrt.png"><img src="'+u+'" alt="Wurde Autoedit-Funktion für Individualdaten deaktivieren angehakt, ist das Bearbeiten von Individualdaten gesperrt. Sie können für einen Datensatz bearbeitet werden, indem explizit über Bearbeiten in den Editormodus gewechselt wird." loading="lazy"></a></p><p><em>Wurde <strong>Autoedit-Funktion für Individualdaten deaktivieren</strong> angehakt, ist das Bearbeiten von Individualdaten gesperrt. Sie können für einen Datensatz bearbeitet werden, indem explizit über Bearbeiten in den Editormodus gewechselt wird.</em></p><p>Unter <em>Verwaltung ➜ Einstellungen ➜ Individuelle Einstellungen</em> lassen sich Optionen setzen, wie die Anzeige und Bedienung von SchILD-NRW für den jeweilig eingeloggten Benutzer ausfällt.</p><p>Unter <strong>Allgemeines</strong> finden sich folgende Optionen:</p><ul><li><strong>In Tabellen horiz./vert. Gitternetzlinien zeigen</strong> legt jeweils fest, ob in den diversen Tabellen von SchILD-NRW die Gitternetzlinien gezeichnet werden.</li><li><strong>Autoedit-Funktion für Individualdaten deaktivieren</strong> verhindert, dass Sie Individualdaten sofort durch Tippen oder Auswählen ändern. Ist die Option aktiviert, müssen Sie zuerst in der Symbolleiste <strong>Bearbeiten</strong> einschalten. In der Standardeinstellung ist die direkte Bearbeitung ohne diesen zusätzlichen Schritt möglich.</li><li><strong>Zusätzliche Kurslehrer in den Leistungsdaten anzeigen</strong>: Mit diesem Haken wird in den Leistungsdaten der Schüler die Spalte mit den Teamteaching-Kollegen im Kursunterricht angezeigt. Diese zusätzlichen Lehrkräfte müssen beim jeweiligen Kurs über <em>Kataloge ➜ Kurse</em> zugewiesen werden.</li><li><strong>Statuswechsel ohne vorherige Filterung auf den Ziel-Status ermöglichen</strong> steuert, wann Sie den Schülerstatus ändern dürfen. Ist die Option aktiviert, kann ein Datensatz nach dem Statuswechsel aus der Namensliste verschwinden, weil der neue Status im aktuellen Filter fehlt. Ist sie ausgeschaltet, müssen Sie den Zielstatus vorher in die Auswahl aufnehmen. Andernfalls zeigt SchILD-NRW 3 beim Änderungsversuch einen Fehlerhinweis.</li><li><strong>Bei Schülerwechsel immer Individualseite anzeigen</strong>: Diese Option bewirkt, dass bei einem Datensatzwechsel im Schülercontainer immer wieder der Karteireiter <em>Individual-Daten I</em> angezeigt wird.</li><li><strong>Schnellfilter aus SchILD2 verwenden</strong> schaltet im Kopfbereich des Schülercontainers den Schellfilter nach <em>Status</em>, <em>Klasse</em>, <em>Jahrgang</em>, <em>Kurs</em>, <em>Abteilung</em> und/oder <em>Schulgliederung</em> frei. Ebenso erscheint das Icon, mit dem der Filter wieder zurückgesetzt werden kann.</li><li><strong>Bei Programmende immer nachfragen</strong> lässt bei Aktivierung ein Fenster erscheinen, in dem noch einmal eine Bestätigung erfragt wird, um SchILD-NRW zu beenden.</li></ul><h2 id="weitere-einstellungen" tabindex="-1">Weitere Einstellungen <a class="header-anchor" href="#weitere-einstellungen" aria-label="Permalink to &quot;Weitere Einstellungen&quot;">​</a></h2><h3 id="benutzeroberflache" tabindex="-1">Benutzeroberfläche <a class="header-anchor" href="#benutzeroberflache" aria-label="Permalink to &quot;Benutzeroberfläche&quot;">​</a></h3><p><a href="/bilder/benutzer-einstellungen/verwaltung-einstellungen-individual-einstellungen-silver-gui.png"><img src="'+g+'" alt="Umstellen der Benutzeroberfläche. Der Standard ist Luna, hier im Screenshot Silver." loading="lazy"></a></p><p><em>Umstellen der Benutzeroberfläche. Der Standard ist Luna, hier im Screenshot Silver.</em></p><p>SchILD-NRW unterstützt unterschiedliche <em>Benutzeroberflächen</em> und <em>Icons</em>.</p><p>Per Standard ist die Oberfläche <em>Luna</em> mit den Symbolen <em>Blue</em> eingestellt und daran richten sich auch alle Screenshots in dieser Dokumentation aus.</p><p>Zum Ändern der Oberfläche muss das Programm neu gestartet werden.</p><p><a href="/bilder/benutzer-einstellungen/verwaltung-einstellungen-individual-einstellungen-farbe-statistik.png"><img src="'+t+'" alt="Stellen Sie die Farbe ein, in der statistikrelevante Felder hervorgehoben werden. Hier im Beispiel wurde hellgrün gewählt." loading="lazy"></a></p><p><em>Stellen Sie die Farbe ein, in der statistikrelevante Felder hervorgehoben werden. Hier im Beispiel wurde hellgrün gewählt.</em></p><p>In SchILD-NRW werden <em>statistikrelevante Felder</em> mit Fettdruck und Sternchen, also etwa <strong>Geburtsdatum*</strong> kenntlich gemacht.</p><p>Über <em>Verwaltung ➜ Einstellungen ➜ Individuelle Einstellungen ➜ Benutzeroberfläche</em> ➜ <strong>Farbe für statistikrelevante Felder</strong> lassen sich diese Überschriften zusätzlich noch einfärben.</p><p>Nach einem Neustart von SchILD-NRW wird die gewählte Farbe bei den statistikrelevanten Feldern verwendet.</p><p><a href="/bilder/benutzer-einstellungen/verwaltung-einstellungen-individual-einstellungen-farbe-statistik-ergebnis.png"><img src="'+o+'" alt="Das Ergebnis mit den eingefärbten Feldbezeichnungen." loading="lazy"></a></p><p><em>Das Ergebnis mit den eingefärbten Feldbezeichnungen.</em></p>',24),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Es ist dringend empfohlen, dass sich jeder Eingaben vornehmende Nutzer hier eine Farbe setzt."),e("p",null,"Wählen Sie Farben mit ausreichend Kontrast zum Hintergrund.")],-1),i('<h3 id="andere" tabindex="-1">Andere <a class="header-anchor" href="#andere" aria-label="Permalink to &quot;Andere&quot;">​</a></h3><p><a href="/bilder/benutzer-einstellungen/verwaltung-einstellungen-individual-einstellungen-andere.png"><img src="'+h+'" alt="Andere individuelle Einstellungen. Individuelle Einstellungen zurücksetzen und Einstellungen zum Email-Kontos des Benutzers. In Fortsetzung des vorherigen Unterthemas in der Oberfläche Light." loading="lazy"></a></p><p><em>Andere individuelle Einstellungen. <strong>Individuelle Einstellungen zurücksetzen</strong> und Einstellungen zum <strong>Email-Konto</strong>s des Benutzers. In Fortsetzung des vorherigen Unterthemas in der Oberfläche Light.</em></p><p>Unter diesem Punkt finden sich zwei Einstellungen:</p><p><strong>Individuelle Einstellungen zurücksetzen</strong>: Sollte es nötig werden, individuell vorgenommene, von den Standardeinstellungen rückgängig zu machen, lässt sich die über diesen Knopf umsetzen.</p><p>SchILD-NRW speichert vorgenommen Einstellungen zu Spaltenbreiten in den diversen Tabellen und auch, welche Schaltflächen wie im Report-Baukasten aktiviert oder angeordnet wurden.</p><p>Wenn sich eine Einstellung nicht mehr auffinden oder rückgängig machen lässt, können Sie die Standardeinstellungen wiederherstellen.</p><p>Weiterhin lässt sich in Bezug auf den Aktuellen Benutzer das <strong>E-Mail-Konto bearbeiten</strong>. Hier können der <strong>Name des Absenders</strong> und die <strong>E-Mailadresse des Absenders</strong> eingetragen werden.</p><p>Damit diese Funktionen Sinn machen, muss SchILD-NRW für die Verwendung von E-Mails korrekt konfiguriert sein (<em>Einstellungen ➜ E-Mail-Versand</em>).</p><h3 id="sichtbare-spalten" tabindex="-1">Sichtbare Spalten <a class="header-anchor" href="#sichtbare-spalten" aria-label="Permalink to &quot;Sichtbare Spalten&quot;">​</a></h3><p><a href="/bilder/benutzer-einstellungen/verwaltung-einstellungen-individual-einstellungen-sichtbare-spalten.png"><img src="'+c+'" alt="Die im Schülercontainer angezeigten Spalten können hier eingestellt werden." loading="lazy"></a></p><p><em>Die im Schülercontainer angezeigten Spalten können hier eingestellt werden.</em></p><p>Über die Haken bei <em>Sichtbare Spalten</em> lässt sich für den eigenen Benutzer einstellen, welche Spalten im Schülercontainer angezeigt werden.</p><p>Je nach persönlicher Aufgabe und Breite des Bildschirms kann es eventuell nützlich sein, weitere Felder zu aktivieren.</p><p>Standardmäßig sind <em>Name</em> und <em>Klasse</em> sichtbar.</p>',15),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Über das Menüband in "),e("em",null,"Schüler"),n(" kann mit "),e("strong",null,"Sortierung"),n(" die Sortierreihenfolge der Personen festgelegt werden.")])],-1),e("h2",{id:"report-schnellzugriff-konfigurieren",tabindex:"-1"},[n("Report-Schnellzugriff konfigurieren "),e("a",{class:"header-anchor",href:"#report-schnellzugriff-konfigurieren","aria-label":'Permalink to "Report-Schnellzugriff konfigurieren"'},"​")],-1),e("p",null,[e("a",{href:"/bilder/benutzer-einstellungen/einstellungen-globale-einstellungen-schnellzugriff-ausschnitt.png"},[e("img",{src:m,alt:"Aktivieren des Schnellzugriffs in den globalen Einstellungen.",loading:"lazy"})])],-1),e("p",null,[e("em",null,"Aktivieren des Schnellzugriffs in den globalen Einstellungen.")],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Diese Einstellung wird nicht in den Individuelle Einstellungen vorgenommen:"),e("p",null,[n("Nachdem Sie in "),e("em",null,"Verwaltung ➜ Einstellungen"),n(" ➜ "),e("strong",null,"Reporteinstellungen"),n(" den Report-Schnellzugriff grundsätzlich aktiviert haben, kann in den "),e("strong",null,"Individuelle Einstellungen"),n(" für den jeweiligen Nutzer der Schnellzugriff mit Reports befüllt werden.")])],-1),i('<p><a href="/bilder/benutzer-einstellungen/einstellungen-individuelle-einstellungen-schnellzugriff-reiter.png"><img src="'+p+'" alt="Unter Verwaltung ➜ Einstellungen ➜ Individuelle Einstellungen findet sich nun der Reiter für den Schnellzugriff." loading="lazy"></a></p><p><em>Unter Verwaltung ➜ Einstellungen ➜ <strong>Individuelle Einstellungen</strong> findet sich nun der Reiter für den Schnellzugriff.</em></p><p>Unter <em>Verwaltung ➜ Einstellungen</em> ➜ <strong>Individuelle Einstellungen</strong> findet sich nun der Reiter für den <strong>Report-Schnellzugriff</strong>.</p><p><a href="/bilder/benutzer-einstellungen/einstellungen-individuelle-einstellungen-schnellzugriff-reports-auswaehlen.png"><img src="'+f+'" alt="Wählen Sie Reports für Ihren Schnellzugriff aus." loading="lazy"></a></p><p><em>Wählen Sie Reports für Ihren Schnellzugriff aus.</em></p><p>In der folgenden Liste lassen sich bis zu zehn Reports auswählen.</p><p>Vergeben Sie eine frei wählbare <strong>Schalterbezeichnung</strong>, dann wählen Sie die <strong>Reportvorlage</strong> aus.</p><p><a href="/bilder/benutzer-einstellungen/einstellungen-individuelle-einstellungen-schnellzugriff-reportschnellzugriff.png"><img src="'+b+'" alt="Der fertige Reportschnellzugriff." loading="lazy"></a></p><p><em>Der fertige Reportschnellzugriff.</em></p><p>Nach einem <code>Neustart</code> von SchILD-NRW 3 steht der Reportschnellzugriff mit den eingestellten Reportvorlagen zur Verfügung.</p><p>Ein Klick auf den Report öffnet den gewohnten Druckdialog.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Individuelle_Einstellungen_(Verwaltung_Einstellungen)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6945.</p>',13)])])}const D=r(z,[["render",v]]);export{A as __pageData,D as default};
